96: int scalar_base64_decode(const char *src, size_t srclen, char *out, size_t *outlen) {
97:   const uint8_t *input = (const uint8_t *)src;
98:   uint8_t *output = (uint8_t *)out;
99:   size_t produced = 0;
100:   if (srclen == 0) {
101:     *outlen = 0;
102:     return 1;
103:   }
104:   if ((srclen & 3) != 0) {
105:     *outlen = 0;
106:     return 0;
107:   }
108: 
109:   const size_t groups = srclen / 4;
110:   const size_t bulk_groups = groups - 1;
111:   size_t i = 0;
112: 
113:   /* Decode two complete quartets per iteration, leaving the last for padding. */
114:   while (i + 1 < bulk_groups) {
115:     if (!decode_full_quartet(input + (i << 2), output + produced)) {
116:       *outlen = produced;
117:       return 0;
118:     }
119:     produced += 3;
120:     if (!decode_full_quartet(input + ((i + 1) << 2), output + produced)) {
121:       *outlen = produced;
122:       return 0;
123:     }
124:     produced += 3;
125:     i += 2;
126:   }
127:   while (i < bulk_groups) {
128:     if (!decode_full_quartet(input + (i << 2), output + produced)) {
129:       *outlen = produced;
130:       return 0;
131:     }
132:     produced += 3;
133:     ++i;
134:   }
135: 
136:   const int tail = decode_final_quartet(input + ((groups - 1) << 2), output + produced);
137:   if (tail < 0) {
138:     *outlen = produced;
139:     return 0;
140:   }
141:   *outlen = produced + (size_t)tail;
142:   return 1;
143: }
