46:                            _mm512_cmp_epu8_mask(chars, nine, _MM_CMPINT_LE);
47:   const __mmask64 plus = _mm512_cmpeq_epi8_mask(chars, _mm512_set1_epi8('+'));
48:   const __mmask64 slash = _mm512_cmpeq_epi8_mask(chars, _mm512_set1_epi8('/'));
49:   const __mmask64 valid = upper | lower | digit | plus | slash;
50:   if (valid != static_cast<__mmask64>(~uint64_t(0))) return false;
51: 
52:   __m512i values = _mm512_sub_epi8(chars, A);
53:   values = _mm512_mask_mov_epi8(
