104:   size_t o = 0;
105:   while (srclen - i >= 3) {
106:     const uint32_t v = (static_cast<uint32_t>(in[i]) << 16) |
107:                        (static_cast<uint32_t>(in[i + 1]) << 8) | in[i + 2];
108:     out[o++] = base64_table_enc[(v >> 18) & 63];
109:     out[o++] = base64_table_enc[(v >> 12) & 63];
110:     out[o++] = base64_table_enc[(v >> 6) & 63];
111:     out[o++] = base64_table_enc[v & 63];
112:     i += 3;
113:   }
114:   if (srclen - i == 1) {
115:     const uint8_t x = in[i];
116:     out[o++] = base64_table_enc[x >> 2];
117:     out[o++] = base64_table_enc[(x & 3) << 4];
118:     out[o++] = '=';
119:     out[o++] = '=';
120:   } else if (srclen - i == 2) {
121:     const uint16_t x = (static_cast<uint16_t>(in[i]) << 8) | in[i + 1];
